31	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
32	            throws DuplicateIdentityException {
33	        String householdId = Households.householdId(request.getLastName(), request.getPostcode());
34	        String identityKey = IdentityKeys.of(request.getTelephone(), request.getEmail(), householdId);
35	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
36	        for (Owner existing : ownerRepository.findAll()) {
37	            if (identityKey.equals(IdentityKeys.of(existing))) {
38	                throw new DuplicateIdentityException(identityKey);
39	            }
40	            if (!sharesHousehold && householdId.equals(householdIdOf(existing))) {
41	                throw new DuplicateIdentityException(householdId);
42	            }
43	        }
44	    }
45	
46	    /** The household an existing owner belongs to, computed from its last name and postcode. */
47	    private static String householdIdOf(Owner existing) {
48	        return Households.householdId(existing.getLastName(), existing.getPostcode());
49	    }
